func (am *AgentManager) GetSocketPath(dveID string) (string, error) {
	if ap, err := am.GetAgent(dveID); err == nil {
		return ap.SocketPath, nil
	}

	// Fallback: the socket might belong to an agent started before this server
	// session (e.g. KNIRVSERVER was restarted while the DVE kept running).
	if am.socketDir == "" {
		return "", fmt.Errorf("no agent running for DVE %s and socketDir is not configured", dveID)
	}
	socketPath := filepath.Join(am.socketDir, fmt.Sprintf("agent-%s.sock", dveID))
	if _, err := os.Stat(socketPath); err != nil {
		return "", fmt.Errorf("no agent running for DVE %s (socket %s not found)", dveID, socketPath)
	}
	conn, err := net.DialTimeout("unix", socketPath, 250*time.Millisecond)
	if err != nil {
		return "", fmt.Errorf("no agent running for DVE %s (socket %s not accepting connections): %w", dveID, socketPath, err)
	}
	conn.Close()
	// Re-register as an AgentProcess so future lookups use the fast path.
	// Mark it healthy since the socket file is present and connectable.
	ap := &AgentProcess{
		DVEID:      dveID,
		SocketPath: socketPath,
		StartedAt:  time.Now(),
	}
	ap.setHealthy(true)
	am.mu.Lock()
	am.agents[dveID] = ap
	am.mu.Unlock()
	return socketPath, nil
}

// InnerAgentClient creates an HTTP client that dials the given DVE's agent
// Unix socket, suitable for forwarding requests to the inner agent API.
func (am *AgentManager) InnerAgentClient(dveID string) (*http.Client, string, error) {
	socketPath, err := am.GetSocketPath(dveID)
	if err != nil {
		return nil, "", err
	}
	client := &http.Client{
		Timeout: 30 * time.Second,
		Transport: &http.Transport{
			DialContext: func(ctx context.Context, _, _ string) (net.Conn, error) {
				return net.DialTimeout("unix", socketPath, 5*time.Second)
			},
		},
	}
	return client, socketPath, nil
}

// ForwardToInnerAgent forwards an HTTP request to the inner agent API on the
// given DVE's agent Unix socket and returns the response.
func (am *AgentManager) ForwardToInnerAgent(dveID, method, path string, body io.Reader) (*http.Response, error) {
	client, socketPath, err := am.InnerAgentClient(dveID)
	if err != nil {
		return nil, err
	}

	req, err := http.NewRequest(method, "http://unix"+path, body)

