// SetWorkspaceResolver sets the callback used to resolve per-DVE workspace roots.
// When non-nil, StartAgent will export KNIRV_AGENTS_DEFAULTS_WORKSPACE for that DVE.
func (am *AgentManager) SetWorkspaceResolver(resolver func(dveID string) (string, error)) {
	am.mu.Lock()
	defer am.mu.Unlock()
	am.workspaceResolver = resolver
}

// applyWorkspaceResolver exports the per-DVE workspace into the subprocess
// environment when a resolver is configured.
func (am *AgentManager) applyWorkspaceResolver(cmd *exec.Cmd, dveID string) {
	am.mu.RLock()
	resolver := am.workspaceResolver
	am.mu.RUnlock()
	if resolver == nil {
		return
	}

	wsPath, err := resolver(dveID)
	if err != nil {
		am.logger.Warn("KNIRVAGENT workspace resolver failed",
			zap.String("dveID", dveID),
			zap.Error(err),
		)

		am.logger.Warn("KNIRVAGENT workspace resolver returned an empty path",
			zap.String("dveID", dveID),
		)
		return
	}

	cmd.Env = append(cmd.Env,
		fmt.Sprintf("KNIRV_AGENTS_DEFAULTS_WORKSPACE=%s", wsPath),
		"KNIRV_AGENTS_DEFAULTS_RESTRICT_TO_WORKSPACE=true",
	)
	am.logger.Info("KNIRVAGENT workspace resolved",
		zap.String("dveID", dveID),
		zap.String("workspace", wsPath),
	)
}

// StartAgent spawns a new KNIRVAGENT subprocess for the given DVE ID.
// It blocks until the agent's socket is ready (up to StartTimeout).
func (am *AgentManager) StartAgent(ctx context.Context, dveID string, startTimeout time.Duration) (*AgentProcess, error) {
	am.mu.Lock()

	// Check if already running
	if existing, ok := am.agents[dveID]; ok && existing.isHealthy() {
		am.mu.Unlock()
		am.logger.Info("Agent already running for DVE", zap.String("dveID", dveID))
		return existing, nil
	}

	// Check max concurrent limit
	if len(am.agents) >= am.maxConcurrent {
		am.mu.Unlock()
		return nil, fmt.Errorf("max concurrent agents reached (%d/%d)",
			len(am.agents), am.maxConcurrent)
	}

	resolvedPath := am.binaryPath
	if resolvedPath == "" {
		var err error
		resolvedPath, err = resolveBinaryPath("./knirvagent")
		if err != nil {
			am.mu.Unlock()
			return nil, fmt.Errorf("KNIRVAGENT binary not found: %w", err)
		}
	}

	if am.socketDir != "" {
		if err := os.MkdirAll(am.socketDir, 0755); err != nil {
			am.mu.Unlock()
			return nil, fmt.Errorf("failed to create socket dir %s: %w", am.socketDir, err)
		}
	}

	socketPath := filepath.Join(am.socketDir, fmt.Sprintf("agent-%s.sock", dveID))

	// Kill any stale instance for this DVE only. Do not touch other agents.
	killStaleAgent(socketPath)
	os.Remove(socketPath)

	am.logger.Info("Starting KNIRVAGENT for DVE",
		zap.String("dveID", dveID),
