		if err := os.MkdirAll(am.socketDir, 0755); err != nil {
			am.mu.Unlock()
			return nil, fmt.Errorf("failed to create socket dir %s: %w", am.socketDir, err)
		}
	}

	socketPath := filepath.Join(am.socketDir, fmt.Sprintf("agent-%s.sock", dveID))

